// Shared helpers (the builder copies these lines into every Code node that needs them).
const nowIso = () => new Date().toISOString();
const clone = (o) => JSON.parse(JSON.stringify(o));
// Airtable formula string literal: double quotes, with backslash and double quote escaped.
const q = (s) => '"' + String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
// Short reason from an n8n HTTP Request error item. error.message looks like 422 - "<body as JSON text>".
function httpError(err) {
  const e = err || {};
  const status = e.status || e.statusCode || (e.response && e.response.status) || '';
  const m = String(e.message || e.description || '');
  let detail = '';
  if (m.indexOf(' - ') > -1) {
    let raw = m.slice(m.indexOf(' - ') + 3);
    try { raw = JSON.parse(raw); } catch (x) { /* not JSON text */ }
    let body = raw;
    try { body = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (x) { body = raw; }
    if (body && typeof body === 'object') {
      if (body.ErrorCode !== undefined) detail = 'Postmark error ' + body.ErrorCode + (body.Message ? ', ' + String(body.Message).split('. ')[0] : '');
      else if (body.error && typeof body.error === 'object') detail = body.error.type || body.error.message || '';
      else if (typeof body.error === 'string') detail = body.error;
      else if (body.errors) detail = typeof body.errors === 'string' ? body.errors : 'GraphQL errors';
    } else if (typeof body === 'string') {
      detail = body;
    }
  } else {
    detail = m;
  }
  detail = String(detail || '').replace(/\s+/g, ' ').trim().slice(0, 160);
  return (status ? 'HTTP ' + status : 'no answer') + (detail ? ', ' + detail : '');
}
// Short reason from Shopify's top level GraphQL "errors" (HTTP 200 with no data), with the code when there is one,
// for example "Throttled" (code THROTTLED, said once) when the query cost bucket is empty.
function gqlError(errors) {
  if (!Array.isArray(errors)) return String(errors || 'unknown error').slice(0, 160);
  const e = errors[0] || {};
  const message = String(e.message || 'unknown error').replace(/\s+/g, ' ').trim().slice(0, 160);
  const code = e.extensions && e.extensions.code ? String(e.extensions.code) : '';
  return message + (code && code.toLowerCase() !== message.toLowerCase() ? ', ' + code : '');
}

// Checks the shared secret and the message fields before anything is saved.
// It never throws: every problem becomes an explicit answer (401, 400 or 503), because a Code node error
// before Respond to Webhook would make n8n answer 200 with an empty body.
function reject(status, error, alert) {
  return [{ json: { ok: false, status, error, alert: !!alert } }];
}
// Constant time comparison, so the answer time does not reveal how much of the secret was right.
function sameSecret(given, expected) {
  const a = String(given || '');
  const b = String(expected || '');
  let diff = a.length ^ b.length;
  for (let i = 0; i < Math.max(a.length, b.length); i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);
  return diff === 0;
}
const text = (v) => (typeof v === 'string' ? v.trim() : (typeof v === 'number' && Number.isFinite(v) ? String(v) : ''));

try {
  const secret = $env.SUPPORT_FORM_SECRET || '';
  const item = $input.first().json;
  const headers = item.headers || {};
  const body = item.body;

  // Fail closed: with no secret configured, nothing gets in.
  if (!secret) return reject(503, 'The support webhook is not configured yet', true);
  if (!sameSecret(headers['x-support-secret'], secret)) return reject(401, 'Missing or wrong X-Support-Secret header');
  if (!body || typeof body !== 'object' || Array.isArray(body)) return reject(400, 'Send the message as a JSON object');

  const problems = [];
  const messageId = text(body.message_id);
  if (!messageId) problems.push('message_id is required');
  else if (messageId.length > 250) problems.push('message_id is longer than 250 characters');
  else if (/[\u0000-\u001f]/.test(messageId)) problems.push('message_id contains control characters');

  const email = text(body.email).toLowerCase();
  if (!/^[^\s@<>",]+@[^\s@<>",]+\.[a-z]{2,}$/.test(email)) problems.push('email is missing or not a valid address');

  const message = typeof body.message === 'string' ? body.message.trim() : '';
  if (!message) problems.push('message is required');
  else if (message.length > 20000) problems.push('message is longer than 20000 characters');

  const channelKey = text(body.channel).toLowerCase().replace(/[\s_-]+/g, '');
  const channel = (!channelKey || channelKey === 'helpform' || channelKey === 'form') ? 'Help Form' : (channelKey === 'email' ? 'Email' : '');
  if (!channel) problems.push('channel must be help_form or email');

  let receivedAt = nowIso();
  if (body.received_at !== undefined && body.received_at !== null && body.received_at !== '') {
    const d = new Date(text(body.received_at));
    if (isNaN(d.getTime())) problems.push('received_at is not a valid date and time');
    else receivedAt = d.toISOString();
  }

  const photos = [];
  const rawPhotos = (body.photos === undefined || body.photos === null) ? [] : body.photos;
  if (!Array.isArray(rawPhotos)) problems.push('photos must be a list');
  else if (rawPhotos.length > 10) problems.push('send at most 10 photos');
  else {
    for (const p of rawPhotos) {
      const url = text(typeof p === 'string' ? p : (p && p.url));
      if (!/^https:\/\/[^\s"<>]+$/i.test(url)) { problems.push('every photo needs an https url'); break; }
      const filename = text(p && p.filename) || url.split('?')[0].split('/').pop() || 'photo.jpg';
      photos.push({ url, filename: filename.slice(0, 200) });
    }
  }

  if (problems.length) return reject(400, problems.join('; '));

  // Name, subject and order number go into single line text fields and email headers, so line breaks and
  // runs of spaces become one space.
  const line = (v, max) => text(v).replace(/\s+/g, ' ').slice(0, max);
  const msg = {
    messageId, channel, receivedAt, email, message, photos,
    name: line(body.name, 200),
    subject: line(body.subject, 250),
    orderNumberForm: line(body.order_number, 50),
  };
  return [{ json: { ok: true, msg, findMessage: { filterByFormula: '{Message ID} = ' + q(messageId), maxRecords: 1, fields: ['Ticket ID', 'Status'] } } }];
} catch (e) {
  return reject(400, 'The request could not be read');
}

