// Reads Claude's forced tool call. If Claude failed (both outputs of the Claude node end here) or answered
// without a valid triage, the message is sorted by keywords instead and will go to a person.
const t = $('Code: Build Ticket').first().json;
const created = $('Airtable: Create Ticket').first().json;
const res = $input.first().json;
const m = t.msg;
const ctx = { ticketId: t.ticketId, recordId: created.records[0].id, msg: m, log: [t.firstLine] };
const log = (line) => ctx.log.push(nowIso() + ' ' + line);

const ISSUE = { melted: 'Melted', damaged: 'Damaged', wrong_item: 'Wrong Item', missing: 'Missing', allergy_question: 'Allergy Question', other: 'Other' };
const SENTIMENT = { positive: 'Positive', neutral: 'Neutral', negative: 'Negative', angry: 'Angry' };

function keywordTriage(msg) {
  const s = (msg.subject + '\n' + msg.message).toLowerCase();
  const has = (re) => re.test(s);
  const safety = has(/\b(reaction|hives|anaphyla\w*|epipen|swell\w*|hospital|got sick|made (me|him|her|them|us) sick|threw up|vomit\w*|rash)\b/);
  let issueType = 'Other';
  if (safety || has(/\b(allerg\w*|nuts?|peanuts?|tree nuts?|gluten|celiac|coeliac|dairy|lactose|vegan|soy|ingredients?|contains?|traces?)\b/)) issueType = 'Allergy Question';
  else if (has(/\b(melt\w*|soft|puddle|liquid|gooey|heat ?damaged?)\b/)) issueType = 'Melted';
  else if (has(/\b(broken|crushed|damaged?|smashed|cracked|torn|dented|squashed)\b/)) issueType = 'Damaged';
  else if (has(/\b(wrong (item|bar|order|product|flavou?r)|not what i ordered|instead of|different (bar|item|product))\b/)) issueType = 'Wrong Item';
  else if (has(/\b(missing|never (arrived|came|got)|not (arrived|received)|did ?n.?t (arrive|get|receive)|lost|where is my|has ?n.?t (arrived|come))\b/)) issueType = 'Missing';
  let sentiment = 'Neutral';
  if (has(/\b(furious|ridiculous|unacceptable|outrageous|disgusted|angry|worst|scam|terrible)\b/) || /!!/.test(s)) sentiment = 'Angry';
  else if (issueType !== 'Other' && issueType !== 'Allergy Question') sentiment = 'Negative';
  else if (has(/\b(thank|thanks|love|great|amazing|delicious)\b/)) sentiment = 'Positive';
  return { issueType, sentiment, safety, orderNumberGiven: '', summary: msg.message.replace(/\s+/g, ' ').slice(0, 200), method: 'Keyword Fallback' };
}

let c = null;
let why = '';
if (res.error) {
  why = httpError(res.error);
} else {
  const block = (res.content || []).find((b) => b && b.type === 'tool_use' && b.name === 'record_triage');
  const i = block && block.input;
  if (!i) why = 'Claude answered without the triage tool call';
  else if (!ISSUE[i.issue_type] || !SENTIMENT[i.sentiment] || typeof i.safety_concern !== 'boolean' || typeof i.order_number !== 'string' || typeof i.summary !== 'string') why = 'Claude returned an incomplete triage';
  else c = { issueType: ISSUE[i.issue_type], sentiment: SENTIMENT[i.sentiment], safety: i.safety_concern, orderNumberGiven: i.order_number.trim().slice(0, 50), summary: i.summary.replace(/\s+/g, ' ').trim().slice(0, 300), method: 'Claude' };
}
if (!c) {
  c = keywordTriage(m);
  c.fallbackReason = why;
  log('Claude unavailable (' + why + '), sorted by keywords as ' + c.issueType + ', sentiment ' + c.sentiment);
} else {
  log('Classified as ' + c.issueType + ' (Claude), sentiment ' + c.sentiment + (c.safety ? ', safety concern' : ''));
}
ctx.classification = c;

// Order number: the form field first, then what Claude read, then a strict pattern in the text (#1234 or "order 1234").
let given = m.orderNumberForm || c.orderNumberGiven;
if (!given) {
  const hit = (m.subject + ' ' + m.message).match(/#\s?\d{4,6}\b|\border\s+(?:number\s+|no\.?\s*)?#?\d{4,6}\b/i);
  if (hit) given = hit[0].trim();
}
const digits = (String(given || '').match(/\d{4,6}/) || [''])[0];
ctx.orderNumberGiven = given || '';
ctx.orderNumber = digits ? '#' + digits : '';

const email = m.email;
const claimFilter = ctx.orderNumber
  ? 'AND({Resolution} = "Replacement Approved", OR(LOWER(TRIM({Customer Email})) = ' + q(email) + ', ARRAYJOIN({Order}) = ' + q(ctx.orderNumber) + '))'
  : 'AND({Resolution} = "Replacement Approved", LOWER(TRIM({Customer Email})) = ' + q(email) + ')';

return [{
  json: {
    ctx,
    lookups: {
      order: {
        filterByFormula: ctx.orderNumber ? '{Order Number} = ' + q(ctx.orderNumber) : 'FALSE()',
        maxRecords: 1,
        fields: ['Order Number', 'Email', 'Customer', 'Shopify Order ID', 'Financial Status', 'Fulfillment Status', 'Order Status',
          'Currency', 'Shipping Name', 'Shipping Address', 'Shipping City', 'Shipping Region', 'Shipping Country', 'Shipping Postal Code',
          'Cold Pack', 'Forecast Max C', 'Cold Pack Shipped', 'Shipped At', 'Expected Delivery', 'Delivered At', 'Tracking Number'],
      },
      customer: { filterByFormula: 'LOWER(TRIM({Email})) = ' + q(email), maxRecords: 10, fields: ['Name', 'Email', 'Shopify Customer ID', 'Record Status'] },
      claims: { filterByFormula: claimFilter, pageSize: 100, sort: [{ field: 'Ticket ID', direction: 'asc' }], fields: ['Ticket ID', 'Customer Email', 'Order', 'Received At'] },
    },
  },
}];

