  return message + (code && code.toLowerCase() !== message.toLowerCase() ? ', ' + code : '');
}

// The triage rules. Claude only classifies; every decision below is plain code, so the same facts always
// give the same outcome and the rules are easy to read and change.
const prev = $('Code: Read Classification').first().json;
const ctx = clone(prev.ctx);
const orderRes = $('Airtable: Find Order').first().json;
const customerRes = $('Airtable: Find Customer').first().json;
const claimsRes = $input.first().json;
const log = (line) => ctx.log.push(nowIso() + ' ' + line);

const num = (v, d) => { const n = parseFloat(v); return Number.isFinite(n) ? n : d; };
const MELT = num($env.MELT_TEMP_C, 27);
const WINDOW = num($env.CLAIM_WINDOW_DAYS, 7);
const LIMIT = num($env.CLAIM_LIMIT, 2);
const today = nowIso().slice(0, 10);                     // calendar days in UTC
const days = (a, b) => Math.round((Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86400000);
const plural = (n, word) => n + ' ' + word + (n === 1 ? '' : 's');
const one = (n) => (Math.round(n * 10) / 10).toFixed(1);
const email = ctx.msg.email;
const c = ctx.classification;
if ($('Wait: Lookup Cooldown').isExecuted) log('Airtable was rate limited during the lookups, so the workflow waited 35 seconds and looked again');

// The order, and whether the sender is the person who placed it.
const rec = (orderRes.records || [])[0];
const o = { number: ctx.orderNumber, found: !!rec, emailMatches: false };
if (rec) {
  const f = rec.fields;
  Object.assign(o, {
    recordId: rec.id,
    orderEmail: String(f.Email || '').trim().toLowerCase(),
    customerIds: f.Customer || [],
    shopifyOrderId: f['Shopify Order ID'] || '',
    financial: f['Financial Status'] || '',
    orderStatus: f['Order Status'] || '',
    currency: f.Currency || 'USD',
    forecast: typeof f['Forecast Max C'] === 'number' ? f['Forecast Max C'] : null,
    coldPack: f['Cold Pack'] || '',
    coldPackShipped: f['Cold Pack Shipped'] === true,
    shippedAt: f['Shipped At'] || '',
    expected: f['Expected Delivery'] || '',
    deliveredAt: f['Delivered At'] || '',
    tracking: f['Tracking Number'] || '',
    ship: {
      name: f['Shipping Name'] || '', address1: f['Shipping Address'] || '', city: f['Shipping City'] || '',
      region: f['Shipping Region'] || '', country: f['Shipping Country'] || '', zip: f['Shipping Postal Code'] || '',
    },
