// (an active record with a Shopify Customer ID wins over duplicates and imports).
const score = (r) => (r.fields['Record Status'] === 'Duplicate' ? 0 : 2) + (r.fields['Shopify Customer ID'] ? 1 : 0);
let customerId = '';
if (o.found && o.emailMatches && o.customerIds.length) customerId = o.customerIds[0];
else {
