const prior = claims.filter((r) => String(r.fields['Customer Email'] || '').trim().toLowerCase() === email);
const sameOrder = o.found ? claims.find((r) => (r.fields.Order || []).includes(o.recordId)) : null;
ctx.history = { priorApproved: prior.length, priorTickets: prior.map((r) => r.fields['Ticket ID']), sameOrderTicket: sameOrder ? sameOrder.fields['Ticket ID'] : '' };
log('Approved replacements already on record for this email: ' + prior.length + ' (limit ' + LIMIT + ')');

const human = (priority, reason) => ({ action: 'human', status: 'Human Queue', resolution: 'Routed to Human', priority, reason });
let d;
if (c.method !== 'Claude') {
  d = human(c.safety ? 'Urgent' : (c.issueType === 'Allergy Question' ? 'High' : 'Normal'),
    'Claude was unavailable (' + c.fallbackReason + '), so the message was sorted by keywords as ' + c.issueType + '. A person must check it.');
} else if (c.safety) {
  d = human('Urgent', 'The customer reports a possible allergic reaction, illness or injury. A person must reply today.');
} else if (c.issueType === 'Allergy Question') {
  d = human('High', 'Allergy and ingredient questions are always answered by a person.');
} else if (c.issueType === 'Other') {
  d = human('Normal', 'Not a delivery problem the automatic rules cover.');
} else if (!o.number) {
  d = { action: 'ask_order', status: 'Waiting on Customer', resolution: 'None', priority: 'Normal', reason: 'No order number in the message, so the customer was asked for it.' };
