} else {
  const delivered = o.deliveredAt ? o.deliveredAt.slice(0, 10) : '';
  if (c.issueType === 'Missing') {
    if (delivered) d = human('High', 'The carrier marked ' + o.number + ' delivered on ' + delivered + ', but the customer says it did not arrive. Check with the carrier.');
    else if (!o.shippedAt) d = human('Normal', o.number + ' has not shipped yet.');
    else if (o.expected && days(today, o.expected) > 0) d = human('High', o.number + ' shipped on ' + o.shippedAt.slice(0, 10) + ', was expected by ' + o.expected + ' and is ' + plural(days(today, o.expected), 'day') + ' late. Open a carrier trace.');
    else d = { action: 'tracking', status: 'Resolved', resolution: 'None', priority: 'Normal', reason: o.number + ' is in transit and not late yet (expected by ' + (o.expected || 'an unknown date') + '). Tracking details sent.' };
  } else if (!delivered) {
    d = human('Normal', o.number + ' is not marked delivered yet.');
  } else {
    const since = days(today, delivered);
    if (since > WINDOW) {
      d = human('Normal', o.number + ' was delivered ' + plural(since, 'day') + ' ago, outside the ' + WINDOW + ' day claim window.');
    } else if (c.issueType === 'Melted') {
      const warm = o.forecast !== null && o.forecast >= MELT;
      const late = o.expected ? days(delivered, o.expected) : 0;
      const reasons = [];
      if (warm && !o.coldPackShipped) reasons.push('warm forecast (' + one(o.forecast) + ' C, limit ' + MELT + ' C) and no cold pack');
      if (late > 0) reasons.push('arrived ' + plural(late, 'day') + ' late (expected ' + o.expected + ', delivered ' + delivered + ')');
      if (reasons.length) {
        d = { action: 'approve', status: 'Auto-Approved', resolution: 'Replacement Approved', priority: 'Normal',
          reason: 'Free replacement approved: ' + reasons.join(' and ') + ', delivered ' + plural(since, 'day') + ' ago (window ' + WINDOW + ' days).' };
      } else if (o.coldPackShipped) {
        d = human('Normal', o.number + ' shipped with a cold pack and arrived on time, so there is no automatic replacement.');
      } else if (o.forecast === null) {
        d = human('Normal', o.number + ' has no forecast on record and arrived on time, so there is no automatic replacement.');
      } else {
        d = human('Normal', 'The forecast for ' + o.number + ' was ' + one(o.forecast) + ' C (below ' + MELT + ' C) and it arrived on time, so there is no automatic replacement.');
      }
    } else if (ctx.msg.photos.length) {
      d = human('Normal', (c.issueType === 'Damaged' ? 'Damage' : 'A wrong item') + ' reported with ' + plural(ctx.msg.photos.length, 'photo') + ' attached, ready for a person to review.');
    } else {
      d = { action: 'photo', status: 'Waiting on Customer', resolution: 'Photo Requested', priority: 'Normal',
        reason: c.issueType === 'Damaged' ? 'Damaged items need a photo first.' : 'Wrong items need a photo of what arrived first.' };
    }
  }
}
