  d.priority = 'High';
  d.reason += ' The customer is angry.';
}
ctx.decision = d;
ctx.replacement = {};
log('Decision ' + d.status + ', ' + d.priority + ' priority. ' + d.reason);

const out = { ctx };
if (d.action === 'approve') {
  // Every replacement draft carries the tag replacement-for-<order number>. The same request that reads the
  // original order also looks for a draft with that tag, so Shopify itself guards against a second replacement,
