const out = { ctx, canReplace: !fail };
if (fail) {
  ctx.replacement.failed = fail;
} else {
  const [firstName, ...rest] = String(o.ship.name || ctx.msg.name || '').trim().split(/\s+/);
  const input = {
    email: o.orderEmail,
    note: 'Free replacement for ' + o.number + ', melted on arrival. Support ticket ' + ctx.ticketId + '.',
    tags: ['replacement', 'delivery-triage', 'ticket-' + ctx.ticketId, ctx.replacement.tag],
    lineItems: lines,
    appliedDiscount: { valueType: 'PERCENTAGE', value: 100, title: 'Melt replacement', description: 'Free replacement for ' + o.number },
    shippingAddress: {
      firstName: firstName || undefined, lastName: rest.join(' ') || undefined, address1: o.ship.address1 || undefined,
      city: o.ship.city || undefined, provinceCode: o.ship.region || undefined, countryCode: o.ship.country || undefined, zip: o.ship.zip || undefined,
    },
    shippingLine: { title: 'Free replacement shipping', priceWithCurrency: { amount: '0.00', currencyCode: o.currency || 'USD' } },
