// Reads the draftOrderCreate answer, or a later draftOrder(id) recheck. Shopify can still be calculating a new
// draft order (DraftOrder.ready is false), and its total is only final once ready is true. So the draft is
// completed only when it is ready and its total is 0. While Shopify is calculating, the workflow waits 2 seconds
// and asks again, at most MAX_CHECKS times; after that a person completes it.
// Two ways in: Shopify: Create Replacement (first run) and Shopify: Recheck Draft (later runs, after the Wait).
const MAX_CHECKS = 3;
const recheck = $('Wait: Draft Calculating').isExecuted;
const ctx = clone(recheck ? $('Wait: Draft Calculating').first().json.ctx : $('Code: Build Replacement').first().json.ctx);
const res = $input.first().json;
const log = (line) => ctx.log.push(nowIso() + ' ' + line);
const r = ctx.replacement;
const what = recheck ? 'the draft order check' : 'the draft order request';
let fail = '';
let draft = null;
if (recheck) r.readyChecks = (r.readyChecks || 0) + 1;
if (res.error) fail = 'Shopify did not answer ' + what + ' (' + httpError(res.error) + ')';
else if (res.errors) fail = 'Shopify refused ' + what + ' (' + gqlError(res.errors) + ')';
else if (recheck) {
  draft = (res.data && res.data.draftOrder) || null;
  if (!draft) fail = 'Shopify no longer finds draft ' + r.draftName;
} else {
  const p = (res.data && res.data.draftOrderCreate) || {};
  if (p.userErrors && p.userErrors.length) fail = 'Shopify did not create the draft order (' + p.userErrors.map((e) => e.message).join('; ') + ')';
  else if (!p.draftOrder) fail = 'Shopify returned no draft order';
  else draft = p.draftOrder;
}

let next = 'stop';
if (draft) {
  if (!recheck) {
    r.draftId = draft.id;
    r.draftName = draft.name;
    log('Replacement draft ' + draft.name + ' created (' + draft.id + ')');
  }
  const checks = r.readyChecks || 0;
  if (draft.ready !== true) {
    if (checks < MAX_CHECKS) {
      next = 'recheck';
      if (!recheck) log('Shopify is still calculating draft ' + r.draftName + ', checking again in 2 seconds');
    } else {
      fail = 'Shopify was still calculating draft ' + r.draftName + ' after ' + MAX_CHECKS + ' checks, so it was not completed';
    }
  } else {
    if (recheck) log('Draft ' + r.draftName + ' is ready after ' + checks + (checks === 1 ? ' check' : ' checks'));
    const total = parseFloat(((draft.totalPriceSet || {}).shopMoney || {}).amount);
    if (total === 0) next = 'complete';
    else fail = 'draft ' + r.draftName + ' totals ' + (Number.isFinite(total) ? total.toFixed(2) : 'an unknown amount') + ' instead of 0, so it was not completed';
