// Writes the customer email for the four automatic outcomes. Tickets for a person get no automatic email:
// a member of the team answers them (allergy questions are never answered automatically).
const ctx = clone($input.first().json.ctx);
const d = ctx.decision;
const m = ctx.msg;
const o = ctx.order || {};
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const day = (iso) => { if (!iso) return ''; const x = new Date(String(iso).length === 10 ? iso + 'T12:00:00Z' : iso); return isNaN(x) ? '' : MONTHS[x.getUTCMonth()] + ' ' + x.getUTCDate(); };
// The greeting uses the first name only when it looks like a name (letters, apostrophes, hyphens), so a link or
// other text typed into the name field never ends up in an email sent from the support address.
const typed = (m.name || '').trim().split(/\s+/)[0] || '';
const first = /^\p{L}[\p{L}'-]{0,39}$/u.test(typed) ? typed : 'there';
const sign = '\n\nDemo Chocolate Co. Support';
const ref = 'Your reference is ' + ctx.ticketId + '.';

let subject = '';
let body = '';
if (d.action === 'approve') {
  subject = 'Your free replacement for order ' + o.number;
  body = 'Hi ' + first + ',\n\nI am sorry your chocolate from order ' + o.number + ' arrived melted. That should not happen, so we are sending you a free replacement.\n\n'
    + 'Your replacement order is ' + ctx.replacement.orderName + '. You do not need to pay anything or send the melted bars back. You will get a shipping email as soon as it leaves our kitchen.\n\n'
    + 'If anything else is wrong, just reply to this email. ' + ref + sign;
} else if (d.action === 'photo') {
  const damaged = ctx.classification.issueType === 'Damaged';
  subject = 'About your order ' + o.number;
  body = 'Hi ' + first + ',\n\nI am sorry your order ' + o.number + (damaged ? ' arrived damaged' : ' arrived with the wrong item') + '. Could you reply to this email with '
    + (damaged ? 'a photo of the box and the bars as they arrived' : 'a photo of what you received, with the label showing') + '? '
    + 'As soon as we have it, we will sort out a replacement or a refund for you.\n\n' + ref + sign;
} else if (d.action === 'tracking') {
  subject = 'Your order ' + o.number + ' is on its way';
  body = 'Hi ' + first + ',\n\nGood news, your order ' + o.number + ' is on its way. It left us on ' + day(o.shippedAt)
    + (o.expected ? ' and the carrier expects to deliver it by ' + day(o.expected) : '') + '.\n\n'
    + (o.tracking ? 'Tracking number ' + o.tracking + '\n\n' : '')
    + 'If it has not arrived by then, reply to this email and we will look into it straight away. ' + ref + sign;
} else if (d.action === 'ask_order') {
  subject = 'Could you send us your order number?';
  body = 'Hi ' + first + ',\n\nThanks for getting in touch, and I am sorry something went wrong. To look into it we need your order number. '
    + 'It starts with # and is in your order confirmation email. Just reply to this email with it.\n\n' + ref + sign;
}

const email = { send: !!body };
if (body) {
  // Replies to an email thread stay in the same thread for the customer.
  if (m.channel === 'Email' && m.subject) {
    const own = m.subject.replace(/\s+/g, ' ').trim().slice(0, 150);
    subject = /^re:/i.test(own) ? own : 'Re: ' + own;
  }
  const msg = {
    From: $env.EMAIL_FROM_SUPPORT,
    To: m.email,
    Subject: subject,
    TextBody: body,
    Tag: 'delivery-triage',
    MessageStream: $env.POSTMARK_MESSAGE_STREAM || 'outbound',
    Metadata: { ticket_id: ctx.ticketId, message_id: m.messageId.slice(0, 80) },
  };
  if (m.channel === 'Email' && /^<[^<>\s]+@[^<>\s]+>$/.test(m.messageId)) {
    msg.Headers = [{ Name: 'In-Reply-To', Value: m.messageId }, { Name: 'References', Value: m.messageId }];
  }
  email.body = msg;
}
return [{ json: { ctx, email } }];

