// Records what happened to the reply email, then prepares the Slack alert for tickets that need a person.
// Three ways in: no email to send, the Postmark answer, or Postmark's error output.
const res = $input.first().json;
let ctx;
let failed = '';
if (res.ctx) {
  ctx = clone(res.ctx);
  if (res.error) failed = httpError(res.error);
} else {
  ctx = clone($('Code: Build Reply').first().json.ctx);
  if (res.ErrorCode === 0 && res.MessageID) ctx.reply = { messageId: res.MessageID, sentAt: nowIso() };
  else failed = 'Postmark error ' + res.ErrorCode + ', ' + String(res.Message || 'unknown');
}
const log = (line) => ctx.log.push(nowIso() + ' ' + line);
const d = ctx.decision;
if (ctx.reply) {
  log('Reply sent to ' + ctx.msg.email + ' (' + { approve: 'replacement confirmation', photo: 'photo request', tracking: 'tracking details', ask_order: 'order number request' }[d.action] + ', Postmark ' + ctx.reply.messageId + ')');
} else if (failed) {
  log('Reply email failed (' + failed + ')');
  d.status = 'Human Queue';
  d.priority = d.priority === 'Urgent' ? 'Urgent' : 'High';
  if (d.resolution !== 'Replacement Approved') d.resolution = 'Routed to Human';
  d.reason += ' The reply email could not be sent (' + failed + '), so a person must contact the customer.';
  d.emailFailed = true;
}

// Slack alert for the human queue. Customer text is escaped so it cannot ping the channel or fake links.
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const slackUrl = $env.SLACK_SUPPORT_WEBHOOK_URL || '';
const alert = { send: d.status === 'Human Queue' && !!slackUrl, configured: !!slackUrl };
if (d.status === 'Human Queue') {
  const c = ctx.classification;
  const o = ctx.order || {};
  const orderLine = !o.number ? 'none given' : (!o.found ? o.number + ' (not found)' : o.number + (o.emailMatches ? ', email matches' : ', email does NOT match the order'));
  const excerpt = ctx.msg.message.replace(/\s+/g, ' ').slice(0, 300) + (ctx.msg.message.length > 300 ? '...' : '');
  alert.text = [
    '*Support ticket for a person* (' + d.priority + ' priority)',
    '*' + ctx.ticketId + '* from ' + esc(ctx.msg.name || 'unknown') + ' (' + esc(ctx.msg.email) + ') via ' + ctx.msg.channel,
    'Issue: ' + c.issueType + ' (' + c.method + '), sentiment ' + c.sentiment,
    'Order: ' + esc(orderLine),
    (ctx.replacement && ctx.replacement.orderName ? 'Replacement: ' + ctx.replacement.orderName + ' created' : ''),
    'Why: ' + esc(d.reason),
    'Summary: ' + esc(c.summary),
    '> ' + esc(excerpt),
  ].filter(Boolean).join('\n');
}
return [{ json: { ctx, alert } }];

