// One Airtable update with everything that happened, so the ticket shows the outcome and the full action log.
// Three ways in: no alert needed, the Slack answer, or Slack's error output.
const res = $input.first().json;
let ctx;
let alert;
let slackError = '';
if (res.ctx) {
  ctx = clone(res.ctx);
  alert = res.alert || {};
  if (res.error) slackError = httpError(res.error);
} else {
  const prev = $('Code: Record Email').first().json;
  ctx = clone(prev.ctx);
  alert = prev.alert;
  alert.sent = true;
}
const log = (line) => ctx.log.push(nowIso() + ' ' + line);
const d = ctx.decision;
if (d.status === 'Human Queue') {
  if (alert.sent) log('Slack alert posted to the support queue');
  else if (slackError) log('Slack alert failed (' + slackError + '), the ticket still waits in the Human Queue');
  else if (!alert.configured) log('No SLACK_SUPPORT_WEBHOOK_URL set, the ticket waits in the Human Queue without an alert');
}

const c = ctx.classification;
const o = ctx.order || {};
const r = ctx.replacement || {};
const fields = {
  'Issue Type': c.issueType,
  'Sentiment': c.sentiment,
  'Classification Method': c.method,
  'Email Matches Order': !!(o.found && o.emailMatches),
  'Status': d.status,
  'Priority': d.priority,
  'Resolution': d.resolution,
  'Routing Reason': d.reason,
  'Action Log': ctx.log.join('\n'),
};
if (o.recordId) fields['Order'] = [o.recordId];
if (ctx.customerRecordId) fields['Customer'] = [ctx.customerRecordId];
if (ctx.orderNumberGiven) fields['Order Number Given'] = ctx.orderNumberGiven;
if (r.draftId) fields['Replacement Draft Order ID'] = r.draftId;
if (r.orderName) fields['Replacement Order Name'] = r.orderName;
if (ctx.reply) {
  fields['Reply Sent At'] = ctx.reply.sentAt;
  fields['Reply Message ID'] = ctx.reply.messageId;
}
const summary = 'Ticket ' + ctx.ticketId + ' was triaged as ' + d.status + ' (' + d.resolution + ', ' + d.priority + ' priority)'
  + (r.orderName ? ', replacement order ' + r.orderName + ' was created' : '')
  + (ctx.reply ? ', the reply email was sent' : ', no email was sent');
return [{ json: { ticketId: ctx.ticketId, summary, update: { records: [{ id: ctx.recordId, fields }], typecast: false } } }];
